const today=()=>new Intl.DateTimeFormat("en-CA",{timeZone:IST_TIMEZONE,year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());
function addDays(date:string,n:number){const d=new Date(`${date}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function fmtHour(h:number){if(h===24)return"12 AM";const s=h>=12?"PM":"AM";return`${h%12||12} ${s}`}
function fmtTime(t:string){const[h,m]=t.split(":").map(Number);const s=h>=12?"PM":"AM";return`${h%12||12}:${String(m).padStart(2,"0")} ${s}`}
function mins(t:string){const[h,m]=t.split(":").map(Number);return h*60+m}
function addMinutesToTime(t:string,delta:number){const total=mins(t)+delta;if(total>24*60)return"";const h=Math.floor(total/60),m=total%60;return`${String(h%24).padStart(2,"0")}:${String(m).padStart(2,"0")}`}
function eventIst(e:ScheduleEvent){const x=zonedRangeParts(e.date,e.startTime,e.endTime,e.timezone||IST_TIMEZONE,IST_TIMEZONE);return{date:x.startDate,startTime:x.startTime,endDate:x.endDate,endTime:x.endTime,durationMinutes:x.durationMinutes}}

function eventClass(e:ScheduleEvent){return` scheduleEvent ${e.eventType} ${e.status}`}

