 const trainerName=(id:string)=>trainerMap.get(id)?.fullName??"Trainer";const courseName=(id:string)=>courseMap.get(id)?.shortTitle||courseMap.get(id)?.title||"Course";const studentName=(id:string)=>studentMap.get(id)?.fullName??"Student";
 const activeOne=useMemo(()=>enrollments.filter(e=>e.status==="active"&&e.enrollmentType==="one_to_one").sort((a,b)=>compareText(studentName(a.studentId),studentName(b.studentId))||compareText(courseName(a.courseId),courseName(b.courseId))),[enrollments,students,courses]);const activeCohorts=useMemo(()=>cohorts.filter(c=>isRunningCohort(c)||isUpcomingCohort(c)).sort((a,b)=>compareText(a.name,b.name)),[cohorts]);
 const availabilityIndex=useMemo(()=>{const m=new Map<string,TrainerAvailability[]>();availability.filter(a=>a.enabled).forEach(a=>{const k=`${a.trainerId}|${a.dayOfWeek}`;m.set(k,[...(m.get(k)??[]),a])});for(const rows of m.values())rows.sort((a,b)=>a.startTime.localeCompare(b.startTime));return m},[availability]);
