 const eventIndex=useMemo(()=>{const ist=new Map<string,ReturnType<typeof eventIst>>();const byTrainerDay=new Map<string,ScheduleEvent[]>();const byDay=new Map<string,ScheduleEvent[]>();for(const e of events){if(["cancelled","rescheduled"].includes(e.status))continue;const x=eventIst(e);ist.set(e.id,x);const days=x.endDate!==x.date?[x.date,x.endDate]:[x.date];for(const d of days){const tk=`${e.trainerId}|${d}`;byTrainerDay.set(tk,[...(byTrainerDay.get(tk)??[]),e]);byDay.set(d,[...(byDay.get(d)??[]),e])}}return{ist,byTrainerDay,byDay}},[events]);
