 async function saveEvent(){setMsg("");if(savingEvent)return;if(form.eventType==="class"&&!/:(00|30)$/.test(form.startTime)){setMsg("Classes must start at :00 or :30.");return;}if(form.eventType==="class"&&!STANDARD_CLASS_DURATIONS_MINUTES.includes(form.durationMinutes)){setMsg("Standard classes must be 1, 1.5, 2 or 2.5 hours.");return;}if(form.eventType!=="class"&&form.endTime<=form.startTime){setMsg("End time must be after start time.");return;}if(form.eventType==="class"&&!addMinutesToTime(form.startTime,form.durationMinutes)){setMsg("Choose an earlier start time so the class finishes before midnight.");return;}const input=deriveForm();if(!input){setMsg(form.eventType==="class"?"Choose a 1-to-1 enrollment or cohort.":"Choose a trainer.");return;}setSavingEvent(true);const r=await createScheduleEvent(input);if(!r.ok){setSavingEvent(false);setMsg("error" in r&&r.error?r.error:"Unable to schedule this item.");return;}setMsg("Schedule updated successfully.");setShowForm(false);setSavingEvent(false);await refresh();}
